/*
 * ps2.h: the fixed public interface of the CMSC 125 Problem Set 2 allocator
 * and address translator.
 *
 * Do not edit this file. It holds the constants, the exit codes, the shared
 * structures, and the module prototypes that the manual's Run Contract
 * defines. The reference solution compiles against this header unchanged.
 *
 * One program holds two machines. The allocator serves the arena, one region
 * the program gets once. The translator serves the segment table, which
 * describes the machine's physical memory. A script drives both.
 */
#ifndef PS2_H
#define PS2_H

#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdint.h>

/* ------------------------------------------------------------------ */
/* The constants. Every one of these is stated in the manual.          */
/* ------------------------------------------------------------------ */

/*
 * A block starts on a multiple of this many bytes, and so does the address
 * the allocator hands out. A request is rounded up to it before the block is
 * measured.
 */
#define PS2_ALIGN 8

/*
 * Every block opens with a header of this many bytes: an 8-byte size and an
 * 8-byte link to the next free block. The payload starts at the block's
 * offset plus this number, and that sum is the address the allocator hands
 * out.
 */
#define PS2_HEADER 16

/*
 * The split threshold. A block is split only when the remainder would still be
 * at least this large. A remainder below it stays inside the block that was
 * handed out, so an allocated block can be smaller than this value: a split
 * hands out exactly what the request needs. The macro name and the report field
 * keep the earlier name, because the field name is part of the printed
 * contract.
 */
#define PS2_MIN_BLOCK 32

/* The arena is a multiple of PS2_ALIGN, and it falls inside these bounds. */
#define PS2_MIN_ARENA 64L
#define PS2_MAX_ARENA 65536L

/* The physical memory the segment table describes. */
#define PS2_MAX_PHYS 1048576L

/* Limits. A script that breaks one is refused before anything runs. */
#define PS2_MAX_HANDLES 256
#define PS2_MAX_BLOCKS 2048
#define PS2_MAX_REQUESTS 2048
#define PS2_MAX_NAME 15
#define PS2_MAX_LINE 511

/* Exit codes. main maps a ps2_status onto one of these. */
#define PS2_EXIT_OK 0
#define PS2_EXIT_REJECTED 65
#define PS2_EXIT_FAULT 70

typedef enum {
    PS2_OK = 0,         /* 0  every request ran */
    PS2_ERR_REJECTED,   /* 65 the command line or the script was refused */
    PS2_ERR_FAULT       /* 70 an ownership error, or the arena ran out */
} ps2_status;

typedef enum {
    PS2_POLICY_FIRST = 0, /* the lowest free block that fits */
    PS2_POLICY_BEST,      /* the smallest free block that fits */
    PS2_POLICY_NEXT       /* the first that fits at or after the cursor */
} ps2_policy;

/* The three rows of the segment table, in the order the table lists them. */
typedef enum {
    PS2_SEG_CODE = 0,
    PS2_SEG_HEAP,
    PS2_SEG_STACK,
    PS2_SEG_COUNT
} ps2_segment_id;

typedef enum {
    PS2_GROW_UP = 0,
    PS2_GROW_DOWN
} ps2_growth;

typedef enum {
    PS2_OP_READ = 0,
    PS2_OP_WRITE,
    PS2_OP_EXEC
} ps2_operation;

typedef enum {
    PS2_TR_OK = 0,   /* the offset translated */
    PS2_TR_BOUNDS,   /* the offset is outside the segment */
    PS2_TR_PROTECT   /* the segment does not allow the operation */
} ps2_translation;

typedef enum {
    PS2_REQ_ALLOC = 0,
    PS2_REQ_FREE,
    PS2_REQ_FREEAT,
    PS2_REQ_TOUCH,
    PS2_REQ_TRANSLATE,
    PS2_REQ_DUMP
} ps2_request_kind;

/* One row of the segment table. prot holds three characters, in the order
 * read, write, execute. A dash means the operation is not allowed. */
typedef struct {
    long base;
    long bound;
    ps2_growth growth;
    char prot[4];
} ps2_segment;

/* One line of the script's request list. Only the fields its kind uses are
 * meaningful. */
typedef struct {
    ps2_request_kind kind;
    char handle[PS2_MAX_NAME + 1]; /* alloc, free, touch */
    long size;                     /* alloc */
    long address;                  /* freeat */
    long offset;                   /* translate */
    ps2_operation op;              /* translate */
    ps2_segment_id segment;        /* translate */
} ps2_request;

/* The whole script: the machine, then the requests, in file order. */
typedef struct {
    long arena;
    ps2_segment segments[PS2_SEG_COUNT];
    ps2_policy policy;
    ps2_request requests[PS2_MAX_REQUESTS];
    size_t count;
    const char *path; /* the script path, for diagnostics */
} ps2_script;

/* One handle the script allocated, and what the allocator did with it. */
typedef struct {
    char handle[PS2_MAX_NAME + 1];
    long requested; /* the size the script asked for */
    long start;     /* the block's offset in the arena */
    long block;     /* the block's size when it was handed out */
    long addr;      /* the address handed out: start + PS2_HEADER */
    bool live;      /* false once the handle is released */
} ps2_allocation;

/* What the allocator reports when the run ends. */
typedef struct {
    long allocated; /* the bytes held by the live handles */
    long free;      /* the bytes in free blocks */
    long largest;   /* the size of the largest free block */
    long blocks;    /* how many free blocks there are */
    long internal;  /* the bytes wasted inside the live blocks */
} ps2_summary;

/* Everything the allocator holds during a run. */
typedef struct {
    const ps2_script *script;
    ps2_allocation allocations[PS2_MAX_HANDLES];
    size_t handles;
    ps2_summary summary;
} ps2_run;

/* A diagnostic message. main prints it to stderr and exits. */
typedef struct {
    char text[256];
} ps2_diag;

/* ------------------------------------------------------------------ */
/* src/arena.c: the given arena. Do not edit.                          */
/* ------------------------------------------------------------------ */

/*
 * Maps one arena of script->arena bytes, once. Call it after the script is
 * loaded and before anything else touches the arena. The mapping is private
 * and anonymous, so no host address reaches the output.
 */
void ps2_arena_open(const ps2_script *script);

/* The arena's first byte, and its size in bytes. */
unsigned char *ps2_arena_base(void);
long ps2_arena_size(void);

/* The smallest multiple of `unit` that is not below `value`. */
long ps2_round_up(long value, long unit);

/*
 * The block header accessors. A block at `offset` holds a size and a link to
 * the next free block, both 8 bytes. A link of -1 ends the list. Pass an
 * offset that a block starts at.
 */
long ps2_block_size(long offset);
void ps2_block_set_size(long offset, long size);
long ps2_block_next(long offset);
void ps2_block_set_next(long offset, long next);

/* ------------------------------------------------------------------ */
/* src/script.c: yours. Read and validate the script file.             */
/* ------------------------------------------------------------------ */

/*
 * Loads the script at path. On PS2_OK the caller may use *out: the machine
 * rows are complete, the table lists code, heap, and stack in that order,
 * every name is unique, and every free or touch names a handle an earlier
 * line allocates. On any other status, writes the stated message to *diag.
 * The policy comes from the command line and is stored in *out.
 */
ps2_status ps2_script_load(const char *path, ps2_policy policy, ps2_script *out,
                           ps2_diag *diag);

/* ------------------------------------------------------------------ */
/* src/alloc.c: yours. The free list over the arena.                   */
/* ------------------------------------------------------------------ */

/*
 * Builds the free list. The arena opens as one free block of the whole arena,
 * so the list starts with one node at offset 0.
 */
void ps2_alloc_init(ps2_run *run);

/*
 * Serves one allocation request. The block is chosen by the policy, split when
 * the remainder is at least PS2_MIN_BLOCK, and recorded in *out. On a failure
 * the arena is left as it was and *diag holds the stated message.
 */
ps2_status ps2_alloc_allocate(ps2_run *run, const char *handle, long size,
                              ps2_allocation *out, ps2_diag *diag);

/*
 * Releases the block a live handle owns, then coalesces it with the
 * neighbours it is adjacent to. Writes the released block's record to *out.
 * On a failure *diag holds the stated message.
 */
ps2_status ps2_alloc_release(ps2_run *run, const char *handle,
                             ps2_allocation *out, ps2_diag *diag);

/*
 * Releases the block at the address the allocator handed out, which a live
 * handle owns. Writes that block's record to *out. On a failure *diag holds
 * the stated message.
 */
ps2_status ps2_alloc_release_at(ps2_run *run, long address,
                                ps2_allocation *out, ps2_diag *diag);

/*
 * Answers a dereference of a handle's payload. Writes the address to
 * *address when the handle is live. On a failure *diag holds the stated
 * message.
 */
ps2_status ps2_alloc_touch(ps2_run *run, const char *handle, long *address,
                           ps2_diag *diag);

/*
 * Copies the free list, in address order, into the caller's arrays. Returns
 * how many blocks the list holds, which is never more than cap.
 */
size_t ps2_alloc_snapshot(const ps2_run *run, long *offsets, long *sizes,
                          size_t cap);

/* Fills *out with the totals the summary line reports. */
void ps2_alloc_summary(const ps2_run *run, ps2_summary *out);

/* ------------------------------------------------------------------ */
/* src/translate.c: yours. The segment table.                          */
/* ------------------------------------------------------------------ */

/*
 * Translates one offset inside one segment. Writes the physical address to
 * *address and returns PS2_TR_OK, or returns the fault the access raises.
 * The bounds are checked before the protection field.
 */
ps2_translation ps2_translate(const ps2_script *script, ps2_segment_id segment,
                              long offset, ps2_operation op, long *address);

/* ------------------------------------------------------------------ */
/* src/report.c: yours. Every line the program writes to stdout.        */
/* ------------------------------------------------------------------ */

/* arena <bytes> align N header N min_block N policy <word> */
void ps2_report_arena(FILE *out, const ps2_script *script);

/* one line per segment row, in table order */
void ps2_report_segments(FILE *out, const ps2_script *script);

/* alloc <handle> size N addr N block N */
void ps2_report_alloc(FILE *out, const ps2_allocation *record);

/* free <handle> addr N block N */
void ps2_report_release(FILE *out, const ps2_allocation *record);

/* freeat <address> block N */
void ps2_report_release_at(FILE *out, const ps2_allocation *record);

/* touch <handle> addr N */
void ps2_report_touch(FILE *out, const char *handle, long address);

/* one dump line per free block, or "dump none" when the list is empty */
void ps2_report_dump(FILE *out, const long *offsets, const long *sizes,
                     size_t count);

/* translate <name> offset N <op> addr N, or ... fault <bounds|protect> */
void ps2_report_translate(FILE *out, ps2_segment_id segment, long offset,
                          ps2_operation op, long address, ps2_translation result);

/* summary allocated N free N largest N blocks N internal N external N.NNNNNN */
void ps2_report_summary(FILE *out, const ps2_summary *summary);

/* result complete, or result faulted */
void ps2_report_result(FILE *out, bool faulted);

#endif /* PS2_H */
